/**
 * Unit tests for verifying trigger input default values are properly applied
 * when fields are not explicitly specified in Fluent code.
 *
 * This tests the fix for the bug where unspecified trigger fields were being
 * set to empty strings instead of using the default values defined in the
 * trigger definition.
 */

import { path } from '@servicenow/sdk-build-core'
import { createTestContext, findInput, getMergedRecordUpdates, unzipInputArray } from './test-utils'

describe('Trigger Input Default Values Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Default value application', () => {
        test('Only mandatory fields specified - all optional fields should use defaults', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'trigger-defaults.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Get the first flow (testTriggerWithOnlyMandatoryFields)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Mandatory field should be present
            expect(val('table')).toBe('incident')

            // Optional fields should have default values (NOT empty strings)
            expect(val('run_on_extended')).toBe('false') // Default from created-trigger.now.ts
            expect(val('run_when_setting')).toBe('both') // Default from created-trigger.now.ts
            expect(val('run_when_user_setting')).toBe('any') // Default from created-trigger.now.ts
            expect(val('run_flow_in')).toBe('any') // Default from created-trigger.now.ts

            // Verify defaults are NOT empty strings
            expect(val('run_on_extended')).not.toBe('')
            expect(val('run_when_setting')).not.toBe('')
            expect(val('run_when_user_setting')).not.toBe('')
        })

        test('Partial fields specified - unspecified fields should use defaults', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'trigger-defaults.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Get the second flow (testTriggerWithPartialFields)
            const trgInst = merged['sys_hub_trigger_instance_v2'][1]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // Specified fields should have user-provided values
            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('priority=1')
            expect(val('run_flow_in')).toBe('foreground')

            // Unspecified optional fields should have default values
            expect(val('run_on_extended')).toBe('false')
            expect(val('run_when_setting')).toBe('both')
            expect(val('run_when_user_setting')).toBe('any')

            // Verify unspecified fields are NOT empty strings
            expect(val('run_on_extended')).not.toBe('')
            expect(val('run_when_setting')).not.toBe('')
            expect(val('run_when_user_setting')).not.toBe('')
        })

        test('Explicit non-default values - should use provided values, not defaults', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'trigger-defaults.now.ts', 'oob-triggers/fluent')

            expect(merged['sys_hub_trigger_instance_v2']).toHaveLength(3)

            // Get the third flow (testTriggerWithExplicitNonDefaults)
            const trgInst = merged['sys_hub_trigger_instance_v2'][2]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // All fields should have user-provided values (not defaults)
            expect(val('table')).toBe('incident')
            expect(val('condition')).toBe('active=true')
            expect(val('run_on_extended')).toBe('true') // Non-default
            expect(val('run_when_setting')).toBe('interactive') // Non-default
            expect(val('run_when_user_setting')).toBe('not_one_of') // Non-default
            expect(val('run_flow_in')).toBe('background')

            // Verify these are not the default values
            expect(val('run_on_extended')).not.toBe('false') // false is the default
            expect(val('run_when_setting')).not.toBe('both') // both is the default
            expect(val('run_when_user_setting')).not.toBe('any') // any is the default
        })

        test('Empty string should not be set for unspecified optional fields', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'trigger-defaults.now.ts', 'oob-triggers/fluent')

            // Check all three flows
            for (const trgInst of merged['sys_hub_trigger_instance_v2']) {
                const inputsArr = unzipInputArray(trgInst.trigger_inputs)

                // Find all choice fields that have defaults
                const choiceFieldsWithDefaults = [
                    'run_on_extended',
                    'run_when_setting',
                    'run_when_user_setting',
                    'run_flow_in',
                ]

                for (const fieldName of choiceFieldsWithDefaults) {
                    const input = findInput(inputsArr, fieldName)
                    if (input) {
                        // Value should never be an empty string for fields with defaults
                        expect(input.value).not.toBe('')
                        expect(input.value).toBeTruthy()
                    }
                }
            }
        })

        test('Verify default values match trigger definition', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'trigger-defaults.now.ts', 'oob-triggers/fluent')

            // Get the first flow (only mandatory fields)
            const trgInst = merged['sys_hub_trigger_instance_v2'][0]
            const inputsArr = unzipInputArray(trgInst.trigger_inputs)
            const val = (name: string) => findInput(inputsArr, name)?.value

            // These defaults are defined in /packages/core/src/flow/built-ins/triggers/created-trigger.now.ts
            const expectedDefaults = {
                run_on_extended: 'false',
                run_when_setting: 'both',
                run_when_user_setting: 'any',
                run_flow_in: 'any',
            }

            // Verify each default matches the trigger definition
            for (const [field, expectedValue] of Object.entries(expectedDefaults)) {
                expect(val(field)).toBe(expectedValue)
            }
        })
    })
})
